import{_ as s,B as l,o as c,c as u,a8 as r,a as d,f as a,E as t,w as i}from"./chunks/framework.CNIpabDg.js";const S=JSON.parse(`{"title":"Executables","description":"This section maps Xila's host executables and bundled WASM guest applications on top of the executable runtime.","frontmatter":{"layout":"doc","docType":"explanation","description":"This section maps Xila's host executables and bundled WASM guest applications on top of the executable runtime."},"headers":[],"relativePath":"explanation/architecture/executables/index.md","filePath":"explanation/architecture/executables/index.md","lastUpdated":1793145952000}`),h={name:"explanation/architecture/executables/index.md"};function p(m,e,b,x,f,g){const n=l("HostReference"),o=l("GuestReference");return c(),u("div",{"data-pagefind-body":!0,"data-pagefind-meta":"date:1793145952000"},[e[7]||(e[7]=r('<h1 id="executables" tabindex="-1">Executables <a class="header-anchor" href="#executables" aria-label="Permalink to &quot;Executables&quot;">​</a></h1><p>This section maps executable crates that run through the <a href="/explanation/architecture/libraries/executable.html">Executable runtime crate</a>, including native host components and bundled WASM guest applications.</p><h2 id="architecture-map" tabindex="-1">Architecture map <a class="header-anchor" href="#architecture-map" aria-label="Permalink to &quot;Architecture map&quot;">​</a></h2><h3 id="runtime-and-dispatch-executables" tabindex="-1">Runtime and dispatch executables <a class="header-anchor" href="#runtime-and-dispatch-executables" aria-label="Permalink to &quot;Runtime and dispatch executables&quot;">​</a></h3><ul><li><p><a href="/explanation/architecture/executables/bindings.html">Bindings</a>: guest/host graphics memory and handle translation within the executable runtime.</p></li><li><p><a href="/explanation/architecture/executables/wasm.html">WASM</a>: Wasmi interpreter, WASI execution, cooperative scheduling, guest loading and guest-side API facade.</p></li><li><p><a href="/explanation/architecture/executables/command_line_shell.html">Command line shell</a>: bounded parser/executor with composition, built-ins, and mounted-binary dispatch.</p></li><li><p><a href="/explanation/architecture/executables/terminal.html">Terminal</a>: graphical terminal device surface that launches the command-line shell.</p></li></ul><p><a href="/explanation/architecture/executables/activity.html">System activity</a> is a native Xila dashboard for uptime, task count and allocator usage, including a bounded demo workload. It lives in Applications and is registered by Platforms; it is not a WASI guest.</p><p>The <a href="/explanation/architecture/executables/debug.html">Debug executable</a> is a native diagnostics service for bounded task/memory inspection, UI snapshots and synthetic input. Its <code>/devices/debug/transport</code> endpoint must be protected by the hosting environment.</p><h3 id="session-and-ui-shell-executables" tabindex="-1">Session and UI shell executables <a class="header-anchor" href="#session-and-ui-shell-executables" aria-label="Permalink to &quot;Session and UI shell executables&quot;">​</a></h3><ul><li><a href="/explanation/architecture/executables/graphical_shell.html">Graphical shell</a>: login and desktop session shell.</li><li><a href="/explanation/architecture/executables/settings.html">Settings</a>: tab-based configuration UI (general/appearance/password/network/about).</li><li><a href="/explanation/architecture/executables/file_manager.html">File manager</a>: VFS-backed graphical file browser.</li></ul><h3 id="bundled-wasm-applications" tabindex="-1">Bundled WASM applications <a class="header-anchor" href="#bundled-wasm-applications" aria-label="Permalink to &quot;Bundled WASM applications&quot;">​</a></h3><ul><li><a href="/explanation/architecture/executables/calculator.html">Calculator</a>: scientific calculator UI and expression engine.</li><li><a href="/explanation/architecture/executables/clock.html">Clock</a>: UTC clock, one saved alarm, stopwatch, and countdown timer.</li><li><a href="/explanation/architecture/executables/pixel_painter.html">Pixel Painter</a>: bounded indexed-canvas drawing application with VFS save/open support.</li><li><a href="/explanation/architecture/executables/text_editor.html">Text Editor</a>: page-based UTF-8 editing with a temporary working copy and bounded memory.</li><li><a href="/explanation/architecture/executables/synth.html">Synth</a>: eight-voice WASM instrument using the audio playback device.</li><li><a href="/explanation/architecture/executables/weather.html">Weather</a>: network-dependent Open-Meteo demonstration guest.</li></ul><p>New native and browser seed images bundle Calculator, Clock, Pixel Painter, Synth, Weather, and Text Editor through <code>/applications/executables/wasm</code> where the matching image build includes them. Existing persistent disks keep their previous binaries; a newer seed does not automatically upgrade an installed filesystem. Other guest applications can use the same runtime without being part of the default bundle.</p><h2 id="shared-executable-model" tabindex="-1">Shared executable model <a class="header-anchor" href="#shared-executable-model" aria-label="Permalink to &quot;Shared executable model&quot;">​</a></h2><ul><li>Host executable crates generally implement <code>ExecutableTrait</code> and are mounted under <code>/applications/executables/*</code> as character devices.</li><li>Launch is performed through <code>executable::execute(context, ...)</code>, which handles permission checks and task spawn using explicit managers. Mounted wrappers and <code>Standard</code> carry the same <code>ExecutableContext</code>.</li><li>WASM applications expose an optional <code>__install</code> entry point; the runtime&#39;s <code>--install</code> mode uses it to create launcher/configuration integration before normal <code>_start</code> execution.</li><li>Several UI executables install launcher shortcuts under <code>/configuration/shared/shortcuts/*.json</code>.</li></ul><h2 id="contract-vs-implementation" tabindex="-1">Contract vs implementation <a class="header-anchor" href="#contract-vs-implementation" aria-label="Permalink to &quot;Contract vs implementation&quot;">​</a></h2><ul><li><strong>Contract</strong>: this map describes executable-level responsibilities and integration points on top of the executable runtime contract.</li><li><strong>Current implementation</strong>: entries and relationships reflect the currently mounted/implemented executables and the browser/native demonstration bundle in Applications and Platforms.</li></ul><h2 id="api-documentation" tabindex="-1">API documentation <a class="header-anchor" href="#api-documentation" aria-label="Permalink to &quot;API documentation&quot;">​</a></h2>',17)),d("p",null,[e[3]||(e[3]=a("The ",-1)),t(n,{crate:"executable"},{default:i(()=>[...e[0]||(e[0]=[a("host executable contract",-1)])]),_:1}),e[4]||(e[4]=a(" defines launch and context APIs. The ",-1)),t(n,{repo:"applications",crate:"wasm"},{default:i(()=>[...e[1]||(e[1]=[a("Wasmi host runtime source",-1)])]),_:1}),e[5]||(e[5]=a(" and ",-1)),t(o,{repo:"applications",crate:"wasm"},{default:i(()=>[...e[2]||(e[2]=[a("guest API source",-1)])]),_:1}),e[6]||(e[6]=a(" document the two sides of guest execution (their separate Rustdoc is not yet deployed on Core Pages).",-1))]),e[8]||(e[8]=r('<h2 id="see-also" tabindex="-1">See also <a class="header-anchor" href="#see-also" aria-label="Permalink to &quot;See also&quot;">​</a></h2><ul><li><a href="/explanation/architecture/libraries/executable.html">Executable runtime crate</a></li><li><a href="/reference/wasm-runtime.html">WASM runtime reference</a></li><li><a href="/reference/container-runtime.html">Headless container runtime</a></li><li><a href="/explanation/architecture/libraries/">Libraries architecture map</a></li></ul>',2))])}const _=s(h,[["render",p]]);export{S as __pageData,_ as default};
